// One item per streamer (Kick channel slug) on the permission list.
const slugs = String($input.first().json.streamers || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(s => /^[a-z0-9_-]{2,30}$/.test(s));
if (!slugs.length) throw new Error('Yayıncı ayarları → streamers boş');
return slugs.map(slug => ({ json: { slug } }));

// Shortlist the most viewed recent clips (fresh ones count double, streamers posted in
// the last 8 hours count less, at most 2 per streamer). The funniest one is chosen later
// from what is actually said in them, not from the view count alone.
const cfg = $('Yayıncı ayarları').first().json;
const state = $getWorkflowStaticData('global');
const used = new Set(state.used || []);
const recent = new Set((state.recent || []).filter(r => Date.now() - r.at < 8 * 3600e3).map(r => r.slug));
const views = c => c.view_count ?? c.views ?? 0;
const score = c => views(c) * (Date.now() - Date.parse(c.created_at) < 48 * 3600e3 ? 2 : 1) * (recent.has(c.channel?.slug) ? 0.3 : 1);

const all = $input.all()
  .flatMap(i => i.json.clips || [])
  .filter(c => c.privacy === 'public' && /^https:\/\/clips\.kick\.com\/[A-Za-z0-9_\/.-]+$/.test(c.video_url || c.clip_url || ''))
  .filter(c => c.duration >= Number(cfg.min_clip_seconds) && c.duration <= Number(cfg.max_clip_seconds))
  .filter(c => views(c) >= Number(cfg.min_views) && !used.has(c.id))
  .sort((a, b) => score(b) - score(a));

const perStreamer = {};
const picked = [];
for (const c of all) {
  const s = c.channel?.slug;
  if ((perStreamer[s] = (perStreamer[s] || 0) + 1) > 2) continue;
  picked.push(c);
  if (picked.length >= Number(cfg.candidates)) break;
}
if (!picked.length) return [];

const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*/, '').replace('T', '-');
const runDir = `${cfg.output_dir}/yayin-${runId}`;
return picked.map((c, i) => ({ json: {
  n: i + 1,
  runDir,
  dir: `${runDir}/aday-${i + 1}`,
  clipId: c.id,
  clipUrl: c.video_url || c.clip_url,
  clipTitle: c.title,
  views: views(c),
  duration: c.duration,
  game: c.category?.name || '',
  streamer: c.channel?.username || c.channel?.slug,
  streamerSlug: c.channel?.slug,
  clipper: c.creator?.username || '',
} }));

// Turn each transcript into short timestamped lines, with sound events such as
// (laughter) kept, and add trending Reels captions as wording examples.
const cands = $('Hazırlığı oku').all().map(i => i.json);
const stt = $('Konuşmayı yazıya dök (ElevenLabs)').all().map(i => i.json);

const lines = words => {
  const out = [];
  let cur = null;
  for (const w of words || []) {
    if (w.type === 'spacing') continue;
    const text = w.type === 'audio_event' ? `${w.text}` : w.text;
    if (!cur || w.start - cur.start > 3 || /[.!?]$/.test(cur.text)) {
      if (cur) out.push(cur);
      cur = { start: w.start, text };
    } else cur.text += ' ' + text;
  }
  if (cur) out.push(cur);
  return out.map(l => `[${l.start.toFixed(1)}] ${l.text}`).join('\n').slice(0, 2500);
};

const blocks = cands.map((c, i) => {
  const t = stt[i] && !stt[i].error ? lines(stt[i].words) : '(döküm alınamadı)';
  return `### ${c.n}. ${c.streamer} | ${c.game} | ${c.views} izlenme | ${c.duration} sn\nKlip başlığı: ${c.clipTitle}\n${t}`;
});

const style = $('Trend Reels örnekleri (Instagram)').all()
  .map(i => i.json)
  .filter(x => x && !x.error && x.caption)
  .map(x => ({ t: String(x.caption).replace(/\s+/g, ' ').slice(0, 160), v: Number(x.videoPlayCount ?? x.videoViewCount ?? x.likesCount ?? 0) }))
  .sort((a, b) => b.v - a.v).slice(0, 12)
  .map(r => `- [${r.v} izlenme] ${r.t}`);

return [{ json: { candidatesText: blocks.join('\n\n'), count: cands.length, styleExamples: style.length ? style.join('\n') : '(örnek alınamadı)' } }];

// Validate Claude's choice and timing, remember the clip so it is never reused, and
// carry the chosen candidate (with its frame) to the layout step.
const cfg = $('Yayıncı ayarları').first().json;
const cands = $('Hazırlığı oku').all().map(i => i.json);
const text = ($input.first().json.content || []).map(c => c.text || '').join('');
const s = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
const idx = Math.max(0, Math.min(cands.length - 1, Number(s.pick) - 1 || 0));
const c = cands[idx];
const stt = $('Konuşmayı yazıya dök (ElevenLabs)').all()[idx]?.json || {};
const words = (stt.words || []).filter(w => w.type === 'word').map(w => ({ text: w.text, start: w.start, end: w.end }));

const maxLen = Number(cfg.max_seconds);
let start = Math.max(0, Number(s.start) || 0);
let end = Math.min(c.duration, Number(s.end) || c.duration);
if (!(end - start >= 6)) { start = 0; end = c.duration; }
if (end - start > maxLen) end = start + maxLen;
let peakAt = Number(s.peak_at);
if (!(peakAt >= start && peakAt <= end)) peakAt = (start + end) / 2;

const state = $getWorkflowStaticData('global');
state.used = (state.used || []).concat(c.clipId).slice(-2000);
state.recent = (state.recent || []).filter(r => Date.now() - r.at < 8 * 3600e3).concat({ slug: c.streamerSlug, at: Date.now() });

return [{ json: { ...c, start, end, peakAt, words, reason: s.reason || '', copy: s } }];

// Webcam / game area from the vision step plus the copy and the word timings, as the
// HyperFrames spec for build-short.mjs. It reaches the shell only as base64.
const c = $('Seçimi doğrula').first().json;
const s = c.copy;
const text = ($input.first().json.content || []).map(x => x.text || '').join('');
let v = {};
try { v = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) { v = {}; }
const box = b => Array.isArray(b) && b.length === 4 && b.every(n => typeof n === 'number' && n >= 0 && n <= 1) ? b.map(n => n.toFixed(3)).join(',') : null;
const cam = box(v.webcam);
const content = box(v.content) || '0,0,1,1';
const focusX = Math.min(Math.max(Number(v.focus_x) || 0.5, 0), 1).toFixed(3);
const layout = cam ? 'split' : 'crop';

const link = `https://kick.com/${c.streamerSlug}`;
const attribution = `🎥 Yayıncı: ${c.streamer} – ${link}\nBu kesit ${c.streamer} yayınından, yayıncının izniyle paylaşılmıştır.`
  + (c.clipper ? `\nKlibi oluşturan: ${c.clipper}` : '');
let title = String(s.title || c.clipTitle).trim();
if (!/#shorts/i.test(title)) title = (title.length > 90 ? title.slice(0, 90) : title) + ' #Shorts';
const tags = [...new Set([...(s.tags || []), c.streamer, c.game, 'kick', 'yayın kesitleri'].map(t => String(t || '').replace(/[<>,]/g, '').trim()).filter(Boolean))].slice(0, 15);
const spec = {
  source: c.video,
  start: c.start, end: c.end, peakAt: c.peakAt,
  cam: cam ? cam.split(',').map(Number) : null,
  content: content.split(',').map(Number),
  focusX: Number(focusX),
  hook: String(s.hook || '').slice(0, 60),
  peakText: String(s.peak_text || '').slice(0, 24),
  freezeText: String(s.freeze_text || 'DUR BİR DAKİKA').slice(0, 24),
  replayText: String(s.end_text || 'TEKRAR').slice(0, 14),
  words: c.words || [],
};

return [{ json: {
  title: title.slice(0, 100),
  description: `${String(s.description || '').trim()}\n\n${attribution}\n\n#Shorts #${String(c.streamer).replace(/[^\p{L}\p{N}]/gu, '')} #yayınkesitleri`,
  tags: tags.join(','),
  specB64: Buffer.from(JSON.stringify(spec), 'utf8').toString('base64'),
  outDir: `${c.runDir}/hyperframes`,
  layout,
} }];

// make-clip.mjs prints one JSON line at the end of stdout.
const lines = String($input.first().json.stdout || '').trim().split('\n');
return [{ json: JSON.parse(lines[lines.length - 1]) }];

const c = $('Seçimi doğrula').first().json;
const clip = $('Kesit sonucunu oku').first().json;
return [{ json: {
  videoId: $input.first().json.id,
  url: `https://youtube.com/shorts/${$input.first().json.id}`,
  title: $('Kesit metinlerini hazırla').first().json.title,
  streamer: c.streamer,
  kickClip: c.clipTitle,
  why: c.reason,
  cut: `${c.start}–${c.end} sn, espri anı ${c.peakAt} sn`,
  layout: clip.layout,
  length: `${clip.duration} sn`,
  captions: clip.captions,
} }];
